#!/usr/bin/env node
// Converts docs/*.md into GitHub wiki pages.
//
//   node .github/scripts/docs-to-wiki.mjs [--src docs] [--out wiki]
//
// - docs/<page>.md -> <out>/<Page-Title>.md (title = first "# " line, spaces become hyphens)
// - docs/README.md -> <out>/Home.md (generated from titles if the file is missing)
// - relative links (page.md, page.md#anchor) point at wiki page names
// - images/x.png -> raw.githubusercontent.com URL of docs/images/x.png
// - writes _Sidebar.md and _Footer.md
// - removes wiki pages it generated earlier whose source no longer exists
// Node built-ins only. Pages that were not generated by this script are never touched.

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { basename, join, resolve } from 'node:path'

const REPO = process.env.GITHUB_REPOSITORY || 'shankar-sachin/get-bouncer'
const RAW_BASE = `https://raw.githubusercontent.com/${REPO}/main/docs/`
const EDIT_BASE = `https://github.com/${REPO}/tree/main/docs`
const MARKER = '<!-- generated from '

const SECTIONS = [
  { title: 'Start', pages: ['getting-started', 'install', 'updates', 'system-requirements'] },
  { title: 'Use Bouncer', pages: ['chat', 'rebound', 'code', 'scheduled-tasks', 'ide', 'models'] },
  { title: 'Reference', pages: ['slash-commands', 'keyboard-shortcuts', 'file-formats', 'settings', 'privacy'] },
  { title: 'Help', pages: ['troubleshooting', 'faq'] },
  { title: 'Build', pages: ['plugins'] },
]

function arg(name, fallback) {
  const i = process.argv.indexOf(name)
  return i > -1 && process.argv[i + 1] ? process.argv[i + 1] : fallback
}

const srcDir = resolve(arg('--src', 'docs'))
const outDir = resolve(arg('--out', 'wiki'))

function titleOf(markdown, fallback) {
  const m = markdown.match(/^# (.+?)\s*$/m)
  return m ? m[1].replace(/[#*`]/g, '').trim() : fallback
}

// GitHub wiki page names: spaces to hyphens, drop characters that break wiki URLs.
function wikiName(title) {
  return title
    .replace(/[\\/:*?"<>|#[\]]/g, '')
    .trim()
    .replace(/\s+/g, '-')
}

const broken = []

function rewriteLinks(markdown, wikiNames, from) {
  return markdown
    .replace(/\]\(([a-z0-9-]+)\.md(#[^)\s]*)?\)/g, (whole, page, anchor = '') => {
      const name = page === 'README' ? 'Home' : wikiNames.get(page)
      if (!name) broken.push(`${from}: ${page}.md`)
      return name ? `](${name}${anchor})` : whole
    })
    .replace(/\]\(images\/([^)\s]+)\)/g, (_, file) => `](${RAW_BASE}images/${file})`)
}

const srcLabel = 'docs'

function header(file) {
  return `${MARKER}${file} -->\n`
}

// Read sources.
if (!existsSync(srcDir)) {
  console.error(`source folder not found: ${srcDir}`)
  process.exit(1)
}
const pages = readdirSync(srcDir)
  .filter((f) => f.endsWith('.md') && f !== 'README.md')
  .sort()
  .map((f) => {
    const slug = basename(f, '.md')
    const body = readFileSync(join(srcDir, f), 'utf8')
    return { file: f, slug, body, title: titleOf(body, slug), wiki: '' }
  })
for (const p of pages) p.wiki = wikiName(p.title)

const wikiNames = new Map(pages.map((p) => [p.slug, p.wiki]))
const bySlug = new Map(pages.map((p) => [p.slug, p]))

// Sidebar groups: known sections first (only pages that exist), then anything unlisted.
const listed = new Set()
const groups = []
for (const s of SECTIONS) {
  const items = s.pages.filter((slug) => bySlug.has(slug))
  items.forEach((slug) => listed.add(slug))
  if (items.length) groups.push({ title: s.title, items })
}
const extra = pages.map((p) => p.slug).filter((slug) => !listed.has(slug))
if (extra.length) groups.push({ title: 'More', items: extra })

// Output.
mkdirSync(outDir, { recursive: true })
const written = new Set()

function write(name, content) {
  writeFileSync(join(outDir, `${name}.md`), content)
  written.add(`${name}.md`)
}

for (const p of pages) {
  const body = rewriteLinks(p.body.replace(/^﻿/, ''), wikiNames, p.file)
  write(p.wiki, header(`${srcLabel}/${p.file}`) + body.trimEnd() + '\n')
}

// Home: docs/README.md, or a generated index when it is missing.
const readmePath = join(srcDir, 'README.md')
if (existsSync(readmePath)) {
  const body = rewriteLinks(readFileSync(readmePath, 'utf8'), wikiNames, 'README.md')
  write('Home', header(`${srcLabel}/README.md`) + body.trimEnd() + '\n')
} else {
  const lines = ['# Bouncer documentation', '']
  for (const g of groups) {
    lines.push(`## ${g.title}`, '')
    for (const slug of g.items) lines.push(`- [${bySlug.get(slug).title}](${wikiNames.get(slug)})`)
    lines.push('')
  }
  write('Home', header(`${srcLabel}/README.md (generated index, no README.md in source)`) + lines.join('\n'))
}

const sidebar = ['**[Home](Home)**', '']
for (const g of groups) {
  sidebar.push(`**${g.title}**`)
  for (const slug of g.items) sidebar.push(`- [${bySlug.get(slug).title}](${wikiNames.get(slug)})`)
  sidebar.push('')
}
write('_Sidebar', header(`${srcLabel}/ (sidebar)`) + sidebar.join('\n'))

write(
  '_Footer',
  header(`${srcLabel}/ (footer)`) +
    `These pages are generated from docs/ in the get-bouncer repo. [Edit them on GitHub](${EDIT_BASE}).\n`,
)

// Remove generated pages whose source is gone. Only files carrying our marker are candidates.
let removed = []
for (const f of readdirSync(outDir)) {
  if (!f.endsWith('.md') || written.has(f)) continue
  const text = readFileSync(join(outDir, f), 'utf8')
  if (text.startsWith(MARKER)) {
    rmSync(join(outDir, f))
    removed.push(f)
  }
}

// Report. Links to pages that do not exist are listed so CI shows them.
for (const b of broken) console.log(`  ! unresolved link in ${b}`)
console.log(`wrote ${written.size} files to ${outDir}`)
for (const f of [...written].sort()) console.log(`  + ${f}`)
for (const f of removed) console.log(`  - ${f} (no source)`)
